  ["The Orbiter"] = "Orbiter",
  ["The Orbiter plays Spoken's voices for quests, places, books and bosses, and the game's voice where Spoken has none."] = "Orbiter воспроизводит голоса Spoken для заданий, мест, книг и боссов и голос игры там, где у Spoken его нет.",
  ["The Orbiter plays the zone's story."] = "Orbiter воспроизводит историю зоны.",
