  ["The land speaks"] = "Земля говорит",
  ["The land tells its stories as you walk (the Orbiter with Spoken)"] = "Земля рассказывает свои истории, пока вы идете (Orbiter со Spoken)",
  ["The screen for the view"] = "Экран для обзора",
