  -- the artist's credit under a hand-drawn dungeon map (ADR 0048, 02.11.2026)
  ["Map by %s"] = "Карта: %s",
  ["Map by %s (%s), used with kind permission. Thank you!"] = "Карта: %s (%s), использована с любезного разрешения. Спасибо!",
